<script module lang="ts">
/**
 * Tabs.Content: one tab’s panel.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/tabs.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { getContext, type Snippet } from 'svelte'

import { attributes, joinSlot } from '@polymorph/svelte'
import styles from '@polymorph/recipes/overlays/tabs.module.css'

export interface TabsContentProps {
  children: Snippet
  /**
   * The value of the tab this panel belongs to.
   */
  value: string
}
</script>

<script lang="ts">
let { children, value }: TabsContentProps = $props()
const joined = joinSlot(undefined, () => ({}))
const owner: Record<string, any> = getContext('polymorph:Tabs') ?? {}
</script>

{@render joined.start?.()
}{#if joined.shown
  }{#if owner.keepMounted || owner.api?.value === value
    }<div
      {...attributes(owner.api?.getContentProps({ value }) ?? {})}
      class={styles.content}
      data-tabs-part="tabpanel"
      data-state={owner.api?.value === value ? 'active' : 'inactive'}
      >{@render children?.()
    }</div
  >{/if
}{/if
}{@render joined.end?.()}
